#include <iostream>
#include <ranges>
#include <vector>
int main() {
    const std::vector<int> numbers{1, 2, 3, 4, 5, 6};
    auto pipeline = numbers | std::views::filter([](int n) { return n % 2 == 0; })
                           | std::views::transform([](int n) { return n * n; });
    for (int value : pipeline) std::cout << value << ' ';
    std::cout << '\n';
}
